package com.kdroid.filter;
import android.app.*;import android.content.*;import android.media.AudioManager;import android.os.*;import android.provider.Settings;import android.widget.*;
public class SettingsActivity extends Activity {
 LinearLayout l; protected void onCreate(Bundle b){super.onCreate(b);show();}
 void show(){l=UI.root(this,"הגדרות"); addSystem("Wi-Fi",Settings.ACTION_WIFI_SETTINGS);addSystem("Bluetooth",Settings.ACTION_BLUETOOTH_SETTINGS);addSystem("תאריך ושעה",Settings.ACTION_DATE_SETTINGS);brightness();volume();Button a=UI.b(this,"מנהל 🔒");a.setOnClickListener(v->startActivity(new Intent(this,AdminActivity.class)));l.addView(a);}
 void addSystem(String s,String action){Button b=UI.b(this,s);b.setOnClickListener(v->startActivity(new Intent(action)));l.addView(b);}
 void brightness(){TextView t=new TextView(this);t.setText("בהירות מסך");l.addView(t);SeekBar s=new SeekBar(this);s.setMax(255);try{s.setProgress(Settings.System.getInt(getContentResolver(),Settings.System.SCREEN_BRIGHTNESS));}catch(Exception e){s.setProgress(128);}s.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean f){if(f&&Settings.System.canWrite(SettingsActivity.this))Settings.System.putInt(getContentResolver(),Settings.System.SCREEN_BRIGHTNESS,Math.max(1,p));}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){if(!Settings.System.canWrite(SettingsActivity.this))startActivity(new Intent(Settings.ACTION_MANAGE_WRITE_SETTINGS,android.net.Uri.parse("package:"+getPackageName())));}});l.addView(s);}
 void volume(){TextView t=new TextView(this);t.setText("עוצמת קול");l.addView(t);AudioManager a=(AudioManager)getSystemService(AUDIO_SERVICE);SeekBar s=new SeekBar(this);int max=a.getStreamMaxVolume(AudioManager.STREAM_MUSIC);s.setMax(max);s.setProgress(a.getStreamVolume(AudioManager.STREAM_MUSIC));s.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean f){if(f)a.setStreamVolume(AudioManager.STREAM_MUSIC,p,0);}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});l.addView(s);}
}